In [ ]: Copied! <pre>from concrete import fhe
from concrete_fhe_toolkit.math.basic import add

def test_add(left, right):
    return add(left, right)

compiler = fhe.Compiler(test_add, {'left': 'encrypted', 'right': 'encrypted'})
inputset = [(3, 1), (-2, -2), (0, 0), (2, 2), (1, 3)]
circuit = compiler.compile(inputset)

for inp in inputset:
    try:
        expected = add(inp[0], inp[1])
        if isinstance(expected, tuple):
            assert tuple(int(x) for x in circuit.encrypt_run_decrypt(*inp)) == expected, f"Failed at {inp}"
        else:
            assert int(circuit.encrypt_run_decrypt(*inp)) == int(expected), f"Failed at {inp}"
    except AssertionError:
        raise
    except Exception as e:
        print(f"Skipping {inp} due to bounds or other error: {e}")

print("add tests passed!")
